import os
import torch


class Config:
    # -------------------------------------------------------------------------
    # Paths and Directories
    # -------------------------------------------------------------------------
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_39"
    SUBMISSION_DIR = "./submission"

    # Metadata files generated by the analysis script
    TRAIN_METADATA = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA = os.path.join(METADATA_DIR, "test.csv")

    # Cache files for processed data (using .npz for numpy arrays)
    TRAIN_CACHE = os.path.join(WORKING_DIR, "train_data.npz")
    VAL_CACHE = os.path.join(WORKING_DIR, "val_data.npz")
    TEST_CACHE = os.path.join(WORKING_DIR, "test_data.npz")
    SCALERS_CACHE = os.path.join(WORKING_DIR, "scalers.npz")

    # Model checkpoint path
    MODEL_PATH = os.path.join(WORKING_DIR, "best_model.pt")

    # Submission file
    SUBMISSION_FILE = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Create working and submission directories if they don't exist
    os.makedirs(WORKING_DIR, exist_ok=True)
    os.makedirs(SUBMISSION_DIR, exist_ok=True)

    # -------------------------------------------------------------------------
    # Data Processing Constants
    # -------------------------------------------------------------------------
    # Atomic mapping for one-hot encoding
    ATOM_MAP = {"Al": 0, "Ga": 1, "In": 2, "O": 3}
    NUM_ATOM_TYPES = len(ATOM_MAP)

    # Number of neighbors for soft-context calculation
    K_NEIGHBORS = 12

    # Target columns in the CSV
    TARGET_COLS = ["formation_energy_ev_natom", "bandgap_energy_ev"]

    # -------------------------------------------------------------------------
    # Feature Dimensions
    # -------------------------------------------------------------------------
    # Atomic Stream Features:
    # 1. Atomic Identity (One-Hot): 4
    # 2. Centered Coordinates (x, y, z): 3
    # 3. Nearest Neighbor Distance (d_min): 1
    # 4. Soft-Neighbor Chemical Context: 4
    # Total Atomic Dimension = 12
    ATOMIC_FEATURE_DIM = 12

    # Global Stream Features:
    # 1. Lattice Vector Lengths (a, b, c): 3
    # 2. Lattice Angles (alpha, beta, gamma): 3
    # 3. Unit Cell Volume: 1
    # 4. Atomic Density: 1
    # 5. Stoichiometry (Al, Ga, In): 3
    # 6. Total Number of Atoms: 1
    # Total Global Dimension = 12
    GLOBAL_FEATURE_DIM = 12

    # -------------------------------------------------------------------------
    # Model Hyperparameters (SCC-WDS)
    # -------------------------------------------------------------------------
    # Wide MLP hidden dimension for atomic encoder
    HIDDEN_DIM = 512

    # Hidden dimension for global encoder
    GLOBAL_HIDDEN_DIM = 256

    # Dropout rate for regularization
    DROPOUT = 0.1

    # -------------------------------------------------------------------------
    # Training Hyperparameters
    # -------------------------------------------------------------------------
    BATCH_SIZE = 64
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-4
    EPOCHS = 200
    PATIENCE = 20  # Early stopping patience

    # Random Seed for reproducibility
    SEED = 42

    # Computation Device
    DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")

    @staticmethod
    def print_config():
        """Prints the current configuration."""
        print("=" * 40)
        print("CONFIG")
        print("=" * 40)
        print(f"Device: {Config.DEVICE}")
        print(f"Batch Size: {Config.BATCH_SIZE}")
        print(f"Learning Rate: {Config.LEARNING_RATE}")
        print(f"Epochs: {Config.EPOCHS}")
        print(f"Atomic Feature Dim: {Config.ATOMIC_FEATURE_DIM}")
        print(f"Global Feature Dim: {Config.GLOBAL_FEATURE_DIM}")
        print(f"Hidden Dim: {Config.HIDDEN_DIM}")
        print(f"K Neighbors: {Config.K_NEIGHBORS}")
        print("=" * 40)
